mat2 rot(float r){
    float i = sin(r);
    float j = cos(r);

    return  mat2(j, -i, i, j);
}

// https://iquilezles.org/articles/distfunctions/
float cyl(vec3 p, float h, float r){
    vec2 d = abs(vec2(length(p.xz),p.y)) - vec2(r,h);
    return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}

// https://iquilezles.org/articles/palettes/
vec3 colorize(float t){
    vec3 a = vec3(
        2.0,
        0.3,
        0.6
    );

    vec3 b = vec3(
        1.,
        0.,
        0.1
    );

    vec3 c = vec3(
        1.3,
        1,
        1
    );

    vec3 d = vec3(
        0.1,
        1.,
        0.
    );

    vec3 col = a + b * cos((3.14159*2.)*(c*t+d));

    return col;
}

float sdf(vec3 p){
    float de = 0.2;

    for(int y=0; y<6; y++){
        for(int x=0; x<4; x++){
            vec3 q = p;
            q.x += (float(x) * 0.2);
            q.z += (float(y) * 0.14);

            q = fract(q) - 0.5;

            float c = cyl(q,0.48,0.023);

            float dmag = 40.;
            float d1 = (
                sin(sin(iTime * 0.1) * (dmag * q.x)) * 
                cos(cos(iTime * 0.2) * (dmag * q.y)) *
                sin(cos(iTime * 0.1) * (dmag * q.z))
            );

            c = mix(c,d1,0.033);

            de = min(de, c);
        }
    }

    return de;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    vec3 origin = vec3(0,0,0);

    vec3 dir = normalize(vec3(uv,1.0));

    dir.yz *= rot(iTime * 0.1);
    dir.xz *= rot(iTime * 0.1);

    origin.y = -(iTime * 0.03);
    origin.z = -(iTime * 0.03);
    vec3 col = vec3(0.);

    float t = 0.0;

    int steps = 60;
    for (int i=0; i < steps; i++){
        vec3 p = origin + dir * t;
        float d = sdf(p);

        t += d;

        col = vec3(i) / float(steps);

        if (d < .0001) break;
        if (t > 5.) break;
    }

    vec3 color_g = colorize(t);
    col = mix(col, color_g, 0.2);

    fragColor = vec4(col,0.);
}
